import React, { useState, useEffect, useCallback, useContext } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPlus, faMoneyBill, faCheck } from '@fortawesome/free-solid-svg-icons';
import { faCcPaypal } from '@fortawesome/free-brands-svg-icons';
import axios from 'axios';
import { CartContext } from '../../App';
import '../../styles/CheckoutPage.css';
import '../../styles/PayPalButton.css';

const CheckoutPage = () => {
  const { setCartItems } = useContext(CartContext);
  const location = useLocation();
  const navigate = useNavigate();

  const { items: selectedItems } = location.state || { items: [] };

  const [processingOrder, setProcessingOrder] = useState(false);
  const [loading, setLoading] = useState(false);
  const [addresses, setAddresses] = useState([]);
  const [selectedAddressId, setSelectedAddressId] = useState('');
  const [showAddressForm, setShowAddressForm] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('CASH_ON_DELIVERY');
  const [newAddress, setNewAddress] = useState({
    street: '',
    city: '',
    state: '',
    zipCode: '',
    country: ''
  });
  const [customerId, setCustomerId] = useState(null);

  useEffect(() => {
    if (selectedItems.length === 0) {
      alert('No items to checkout. Redirecting to cart.');
      navigate('/cart');
    }
  }, [selectedItems, navigate]);

  useEffect(() => {
    const storedUser = localStorage.getItem('currentUser');
    if (storedUser) {
      try {
        const userData = JSON.parse(storedUser);
        if (userData && userData.customerId) {
          setCustomerId(userData.customerId);
        }
      } catch (error) {
        console.error('Error parsing user data:', error);
      }
    }
  }, []);

  const fetchAddresses = useCallback(async () => {
    if (!customerId) return;
    try {
      const response = await axios.get(`http://localhost:8080/api/checkout/${customerId}/addresses`);
      setAddresses(response.data);
      if (response.data.length > 0) {
        setSelectedAddressId(response.data[0].id);
      }
    } catch (error) {
      console.error('Error fetching addresses:', error);
      alert('Failed to load addresses.');
    }
  }, [customerId]);

  useEffect(() => {
    if (customerId) {
      fetchAddresses();
    }
  }, [customerId, fetchAddresses]);

  const handleAddressChange = (e) => {
    const { name, value } = e.target;
    setNewAddress(prev => ({ ...prev, [name]: value }));
  };

  const handleAddAddress = async (e) => {
    e.preventDefault();
    if (!customerId) return;
    try {
      setProcessingOrder(true);
      const response = await axios.post(`http://localhost:8080/api/checkout/${customerId}/address`, newAddress);
      setAddresses(prev => [...prev, response.data]);
      setSelectedAddressId(response.data.id);
      setNewAddress({ street: '', city: '', state: '', zipCode: '', country: '' });
      setShowAddressForm(false);
    } catch (error) {
      console.error('Error adding address:', error);
      alert('Failed to add address.');
    } finally {
      setProcessingOrder(false);
    }
  };

  const generateCODTransactionId = () => {
    const timestamp = new Date().getTime();
    const randomNum = Math.floor(Math.random() * 10000);
    return `COD_${timestamp}_${randomNum}`;
  };

  const handleCheckout = async () => {
    if (!selectedAddressId) {
      alert('Please select a shipping address');
      return;
    }
    setProcessingOrder(true);
    setLoading(true);

    try {
      if (paymentMethod === 'PAYPAL') {
        const response = await axios.post(`http://localhost:8080/api/paypal/create?customerId=${customerId}&addressId=${selectedAddressId}`);
        if (response.data && response.data.redirectUrl) {
          localStorage.setItem('paypalPaymentId', response.data.paymentId);
          window.location.href = response.data.redirectUrl;
        } else {
          throw new Error('Failed to initiate PayPal payment');
        }
      } else {
        const orderRequest = {
          customerId,
          addressId: selectedAddressId,
          paymentMethod: 'CASH_ON_DELIVERY',
          transactionId: generateCODTransactionId(),
          cartItems: selectedItems.map(item => ({
            id: item.productId,
            name: item.name,
            price: item.price,
            quantity: item.quantity,
            image: item.image,
            size: item.size,
          })),
        };
        const response = await axios.post('http://localhost:8080/api/orders/create', orderRequest);
        if (response.data) {
          setCartItems([]);
          navigate(`/payment-success?method=cod&orderId=${response.data.id}`);
        } else {
          throw new Error('Failed to create COD order');
        }
      }
    } catch (error) {
      console.error('Error during checkout:', error);
      const errorMessage = error.response?.data?.message || error.response?.data || 'An error occurred during checkout.';
      alert(errorMessage);
    } finally {
      setProcessingOrder(false);
      setLoading(false);
    }
  };

  const calculateTotal = () => {
    return selectedItems.reduce((sum, item) => {
        const itemPrice = typeof item.price === 'string' 
          ? parseInt(item.price.replace(/\D/g, ''))
          : item.price;
        return sum + (item.quantity * itemPrice);
      }, 0);
  };

  const total = calculateTotal();

  const formatPrice = (price) => {
    if (typeof price === 'string') {
        price = parseInt(price.replace(/\D/g, ''), 10);
    }
    return price.toLocaleString('en-US');
  };

  if (selectedItems.length === 0) {
    return null; 
  }

  return (
    <div className="checkout-page-container">
      <div className="checkout-container">
        <h2>Checkout</h2>

        <div className="checkout-section">
          <h3>Shipping Address</h3>
          {addresses.length > 0 && (
            <div className="address-selection">
              <select value={selectedAddressId} onChange={(e) => setSelectedAddressId(e.target.value)} className="address-select">
                {addresses.map(address => (
                  <option key={address.id} value={address.id}>
                    {`${address.street}, ${address.city}, ${address.state}, ${address.zipCode}, ${address.country}`}
                  </option>
                ))}
              </select>
            </div>
          )}
          {!showAddressForm ? (
            <button className="add-address-btn" onClick={() => setShowAddressForm(true)}>
              <FontAwesomeIcon icon={faPlus} /> Add New Address
            </button>
          ) : (
            <form className="address-form" onSubmit={handleAddAddress}>
              <div className="form-group"><label>Street:</label><input type="text" name="street" value={newAddress.street} onChange={handleAddressChange} required /></div>
              <div className="form-group"><label>City:</label><input type="text" name="city" value={newAddress.city} onChange={handleAddressChange} required /></div>
              <div className="form-group"><label>State:</label><input type="text" name="state" value={newAddress.state} onChange={handleAddressChange} required /></div>
              <div className="form-group"><label>Zip Code:</label><input type="text" name="zipCode" value={newAddress.zipCode} onChange={handleAddressChange} required /></div>
              <div className="form-group"><label>Country:</label><input type="text" name="country" value={newAddress.country} onChange={handleAddressChange} required /></div>
              <div className="form-buttons">
                <button type="submit" className="save-address-btn" disabled={processingOrder}>Save Address</button>
                <button type="button" className="cancel-btn" onClick={() => setShowAddressForm(false)}>Cancel</button>
              </div>
            </form>
          )}
        </div>

        <div className="checkout-section">
          <h3>Payment Method</h3>
          <div className="payment-options">
            <div className={`payment-option ${paymentMethod === 'CASH_ON_DELIVERY' ? 'selected' : ''}`} onClick={() => setPaymentMethod('CASH_ON_DELIVERY')}>
              <FontAwesomeIcon icon={faMoneyBill} />
              <span>Cash on Delivery</span>
              {paymentMethod === 'CASH_ON_DELIVERY' && <FontAwesomeIcon icon={faCheck} className="check-icon" />}
            </div>
            <div className={`payment-option ${paymentMethod === 'PAYPAL' ? 'selected' : ''}`} onClick={() => setPaymentMethod('PAYPAL')}>
              <FontAwesomeIcon icon={faCcPaypal} />
              <span>PayPal</span>
              {paymentMethod === 'PAYPAL' && <FontAwesomeIcon icon={faCheck} className="check-icon" />}
            </div>
          </div>
        </div>

        <div className="order-summary">
          <h3>Order Summary</h3>
          <div className="summary-items">
            {selectedItems.map(item => (
              <div key={item.id} className="summary-item">
                <span className="item-name">{item.name} (x{item.quantity})</span>
                <span className="item-price">${formatPrice(item.price * item.quantity)}</span>
              </div>
            ))}
          </div>
          <div className="summary-total">
            <strong>Total:</strong>
            <strong>${formatPrice(total)}</strong>
          </div>
        </div>

        <button className="btn brown-bg place-order-btn" onClick={handleCheckout} disabled={processingOrder || loading}>
          {loading ? 'Processing...' : `Place Order (${paymentMethod === 'PAYPAL' ? 'via PayPal' : 'COD'})`}
        </button>
      </div>
    </div>
  );
};

export default CheckoutPage;
